package engine

// The locale data the Intl constructors with locale data share
// (NumberFormat, PluralRules, DateTimeFormat) and the realm's default
// locale: which locales have number and date data (intl_supp_tables.go,
// generated by internal/gen/cldr from its dataLocales), ResolveLocale with
// relevant extension keys (ECMA-402 §9.2.7), the numbering systems with
// simple digit mappings and CLDR's timeData.
//
// The available locales of a constructor with locale data are the CLDR
// locales that inherit one of the data locales' data, by CLDR's parent
// locales from the locale, or from the locale with its likely script when
// that is not its language's: en-GB (en_001, en), zh-TW (zh-Hant), zh-HK
// (zh-Hant-HK, zh-Hant), zh-SG (zh-Hans-SG). A locale resolves to the
// longest of them that is a prefix of it (the lookup matcher), else to the
// default locale (sv-SE: en-US). Each formats with the data CLDR gives it:
// a regional locale whose data differs from its parent's has a data index
// of its own (intlSubLocales: en-001, en-GB, zh-Hant-HK, ...), whose
// records are deltas of its parent's, applied on first use; any other
// shares its nearest ancestor's (en-AG has en-001's).

import (
	"strings"
	"sync"
)

// intlDataIndex returns the data index of an available locale of the
// constructors with locale data, false when the locale is not one.
func intlDataIndex(tag string) (int, bool) {
	recs := intlDataRecords()
	lo, hi := 0, len(recs)-1
	for lo < hi {
		m := int(uint(lo+hi) >> 1)
		if intlDataAvailable[recs[m]:recs[m+1]-4] < tag {
			lo = m + 1
		} else {
			hi = m
		}
	}
	if lo < len(recs)-1 && intlDataAvailable[recs[lo]:recs[lo+1]-4] == tag {
		return intlIndex36(intlDataAvailable[recs[lo+1]-3:]), true
	}
	return 0, false
}

// intlIndex36 reads a data index as the tables write it: two base-36
// digits.
func intlIndex36(s string) int {
	d := func(c byte) int {
		if c <= '9' {
			return int(c - '0')
		}
		return int(c-'a') + 10
	}
	return d(s[0])*36 + d(s[1])
}

// intlDataRecords holds the offset of each record of intlDataAvailable and
// its length.
var intlDataRecords = sync.OnceValue(func() []uint16 {
	recs := make([]uint16, 1, strings.Count(intlDataAvailable, ";")+1)
	for i := 0; i < len(intlDataAvailable); i++ {
		if intlDataAvailable[i] == ';' {
			recs = append(recs, uint16(i+1))
		}
	}
	return recs
})

// intlHasData reports whether a locale is an available locale of the
// constructors with locale data.
func intlHasData(tag string) bool {
	_, ok := intlDataIndex(tag)
	return ok
}

// intlSubLocale is a regional locale with data of its own.
type intlSubLocale struct {
	tag    string
	parent int // the data index its records are deltas of
}

// intlSubLocaleList decodes intlSubLocales.
var intlSubLocaleList = sync.OnceValue(func() []intlSubLocale {
	list := make([]intlSubLocale, 0, intlSubLocaleCount)
	for s := intlSubLocales; s != ""; {
		end := strings.IndexByte(s, ';')
		list = append(list, intlSubLocale{tag: s[:end-3], parent: intlIndex36(s[end-2:])})
		s = s[end+1:]
	}
	return list
})

// intlDataBase returns the data locale a data index descends from: itself,
// or a regional locale's.
func intlDataBase(i int) int {
	for i >= intlDataLocaleCount {
		i = intlSubLocaleList()[i-intlDataLocaleCount].parent
	}
	return i
}

// intlLocaleTable is a table of records by data index: the data locales'
// own, and the regional locales' deltas of their parent's record, applied
// once, on first use, into recs (zero-valued arrays of their own, so that
// they take no room in the binary).
type intlLocaleTable struct {
	base *[intlDataLocaleCount]string
	sub  *[intlSubLocaleCount]string
	recs *[intlSubLocaleCount]intlSubRecord
}

// intlSubRecord is a regional locale's record of a table, built once.
type intlSubRecord struct {
	once sync.Once
	s    string
}

var (
	intlNumberSubRecs, intlCurrencySubRecs, intlUnitSubRecs, intlDateSubRecs, intlTZSubRecs [intlSubLocaleCount]intlSubRecord

	intlNumberTable   = intlLocaleTable{&intlNumberLocaleData, &intlNumberSubData, &intlNumberSubRecs}
	intlCurrencyTable = intlLocaleTable{&intlCurrencyNames, &intlCurrencySubNames, &intlCurrencySubRecs}
	intlUnitTable     = intlLocaleTable{&intlUnitData, &intlUnitSubData, &intlUnitSubRecs}
	intlDateTable     = intlLocaleTable{&intlDateRecords, &intlDateSubRecords, &intlDateSubRecs}
	intlTZTable       = intlLocaleTable{&intlTZLocaleNames, &intlTZSubNames, &intlTZSubRecs}
)

// record returns the record of a data index.
func (t *intlLocaleTable) record(i int) string {
	if i < intlDataLocaleCount {
		return t.base[i]
	}
	k := i - intlDataLocaleCount
	e := &t.recs[k]
	e.once.Do(func() { e.s = intlApplyDelta(t.record(intlSubLocaleList()[k].parent), t.sub[k]) })
	return e.s
}

// intlApplyDelta returns the record a delta makes of its parent's: runs of
// three uvarints, the bytes of the parent copied, the bytes of the parent
// skipped and the length of an insertion, then the insertion's bytes; the
// rest of the parent follows the last run. An empty delta is the parent.
func intlApplyDelta(parent, delta string) string {
	if delta == "" {
		return parent
	}
	var b strings.Builder
	b.Grow(len(parent) + len(delta))
	p := 0
	for i := 0; i < len(delta); {
		var v [3]int
		for k := range v {
			for shift := 0; ; shift += 7 {
				c := delta[i]
				i++
				v[k] |= int(c&0x7f) << shift
				if c < 0x80 {
					break
				}
			}
		}
		b.WriteString(parent[p : p+v[0]])
		p += v[0] + v[1]
		b.WriteString(delta[i : i+v[2]])
		i += v[2]
	}
	b.WriteString(parent[p:])
	return b.String()
}

// intlDataLocale returns the tag of a data index ("zh-Hant", "en-GB").
func intlDataLocale(i int) string {
	if i >= intlDataLocaleCount {
		return intlSubLocaleList()[i-intlDataLocaleCount].tag
	}
	s := intlDataLocales
	for range i {
		s = s[strings.IndexByte(s, ',')+1:]
	}
	if end := strings.IndexByte(s, ','); end >= 0 {
		return s[:end]
	}
	return s
}

// realmIntl is a realm's Intl state (realmHost.intl): its default locale
// and the formatters of the toLocaleString methods (intl_tolocale.go).
type realmIntl struct {
	// locale is the default locale (RealmOptions.Locale), canonical and
	// without a Unicode extension; "" means intlDefaultLocale.
	locale string
	cache  realmIntlCache
}

// Locale returns the realm's default locale (RealmOptions.Locale).
func (r *Realm) Locale() string {
	if r.host != nil && r.host.intl != nil && r.host.intl.locale != "" {
		return r.host.intl.locale
	}
	return intlDefaultLocale
}

// SetLocale sets the realm's default locale, the locale of the Intl
// constructors and the toLocaleString methods when the script names none:
// a BCP 47 language tag, canonicalized, without its Unicode extension (the
// -u- keywords, which ECMA-402's DefaultLocale never has). "" or a tag that
// is not well-formed restores the default, "en-US". The constructors with
// locale data fall back from a locale without data by truncation, then to
// "en-US".
func (r *Realm) SetLocale(tag string) {
	canon := ""
	if tag != "" {
		if t, ok := canonicalizeLangTag(tag); ok {
			canon = intlRemoveUnicodeExtension(t)
		}
	}
	if canon == intlDefaultLocale {
		canon = ""
	}
	if r.host == nil || r.host.intl == nil {
		if canon == "" {
			return
		}
		r.intlState()
	}
	r.host.intl = &realmIntl{locale: canon}
}

// intlState returns the realm's Intl state, creating it on first use.
func (r *Realm) intlState() *realmIntl {
	if r.host == nil {
		r.host = &realmHost{}
	}
	if r.host.intl == nil {
		r.host.intl = &realmIntl{}
	}
	return r.host.intl
}

// intlDefaultFor returns the locale a constructor whose available locales
// avail tells resolves to when no requested locale is available: the
// realm's default locale, or its longest available prefix, else
// intlDefaultLocale.
func (r *Realm) intlDefaultFor(avail func(string) bool) string {
	loc := r.Locale()
	if loc == intlDefaultLocale {
		return loc // available in every constructor, without a lookup
	}
	if m := intlLookupIn(loc, avail); m != "" {
		return m
	}
	return intlDefaultLocale
}

// intlRemoveUnicodeExtension returns the canonical tag without its Unicode
// locale extension sequence: from the singleton "u" to the next singleton.
// Private use comes last and is not searched.
func intlRemoveUnicodeExtension(tag string) string {
	start := -1
	for i := 0; i+2 < len(tag); i++ {
		if tag[i] != '-' || tag[i+2] != '-' {
			continue
		}
		switch {
		case start >= 0:
			return tag[:start] + tag[i:]
		case tag[i+1] == 'x':
			return tag
		case tag[i+1] == 'u':
			start = i
		}
	}
	if start < 0 {
		return tag
	}
	return tag[:start]
}

// intlUnicodeExtension returns the Unicode locale extension of a canonical
// tag without its "u-" ("ca-gregory-nu-latn"), "" when it has none.
func intlUnicodeExtension(tag string) string {
	start := -1
	for i := 0; i+2 < len(tag); i++ {
		if tag[i] != '-' || tag[i+2] != '-' {
			continue
		}
		switch {
		case start >= 0:
			return tag[start:i]
		case tag[i+1] == 'x':
			return ""
		case tag[i+1] == 'u':
			start = i + 3
		}
	}
	if start < 0 {
		return ""
	}
	return tag[start:]
}

// intlKeyword returns the value of a key in a Unicode extension
// ("ca-gregory-nu-latn", "nu" → "latn"): "" for a key without a value
// ("kn"), and false when the key is absent.
func intlKeyword(ext, key string) (string, bool) {
	for ext != "" {
		end := strings.IndexByte(ext, '-')
		if end < 0 {
			end = len(ext)
		}
		sub := ext[:end]
		ext = ext[min(end+1, len(ext)):]
		if len(sub) != 2 || sub != key {
			continue
		}
		// The value: the subtags up to the next key (two characters).
		n := 0
		for n < len(ext) {
			e := strings.IndexByte(ext[n:], '-')
			if e < 0 {
				e = len(ext) - n
			}
			if e == 2 {
				break
			}
			n += e + 1
		}
		return strings.TrimSuffix(ext[:min(n, len(ext))], "-"), true
	}
	return "", false
}

// intlRelevantKey is a relevant extension key of a constructor for
// intlResolve: the key, the option that sets it (nil when undefined) and
// the key's locale data, its supported values for a data locale with the
// default first ("" standing for null).
type intlRelevantKey struct {
	key    string
	option *String
	values func(dataLocale string) []string
}

// intlResolved is the result of ResolveLocale.
type intlResolved struct {
	locale     string    // [[locale]]: the found locale with the supported keywords
	dataLocale string    // [[dataLocale]]
	values     [3]string // the value of each relevant key in order ("" for null)
}

// intlResolve implements ResolveLocale (ECMA-402 §9.2.7) with the lookup
// matcher for both matchers, the available locales avail tells and up to
// three relevant extension keys.
func (r *Realm) intlResolve(requested []string, avail func(string) bool, keys []intlRelevantKey) intlResolved {
	var res intlResolved
	found, ext := "", ""
	for _, l := range requested {
		if m := intlLookupIn(l, avail); m != "" {
			found, ext = m, intlUnicodeExtension(l)
			break
		}
	}
	if found == "" {
		found = r.intlDefaultFor(avail)
	}
	res.dataLocale = found
	var supported []string // "key-value" or "key"
	for i, k := range keys {
		data := k.values(found)
		value := ""
		if len(data) > 0 {
			value = data[0]
		}
		keyword := ""
		if req, ok := intlKeyword(ext, k.key); ok {
			if req != "" {
				if intlContains(data, req) {
					value, keyword = req, k.key+"-"+req
				}
			} else if intlContains(data, "true") {
				value, keyword = "true", k.key
			}
		}
		if k.option != nil {
			ov := langTagCanonicalUValue(k.key, k.option.GoString())
			if ov == "" {
				ov = "true"
			}
			if ov != value && intlContains(data, ov) {
				value, keyword = ov, ""
			}
		}
		if keyword != "" {
			supported = append(supported, keyword)
		}
		res.values[i] = value
	}
	res.locale = found
	if len(supported) > 0 {
		// The keys are two characters: sorting the keywords sorts the keys.
		for i := 1; i < len(supported); i++ {
			for j := i; j > 0 && supported[j] < supported[j-1]; j-- {
				supported[j], supported[j-1] = supported[j-1], supported[j]
			}
		}
		res.locale = found + "-u-" + strings.Join(supported, "-")
	}
	return res
}

func intlContains(list []string, s string) bool {
	for _, v := range list {
		if v == s {
			return true
		}
	}
	return false
}

// intlDigitTable maps the numbering systems with simple digit mappings to
// their digits.
var intlDigitTable = sync.OnceValue(func() map[string]*[10]rune {
	m := make(map[string]*[10]rune, strings.Count(intlNumberingDigits, ";"))
	s := intlNumberingDigits
	for s != "" {
		end := strings.IndexByte(s, ';')
		id, digits, _ := strings.Cut(s[:end], ":")
		var d [10]rune
		i := 0
		for _, c := range digits {
			d[i] = c
			i++
		}
		m[id] = &d
		s = s[end+1:]
	}
	return m
})

// intlDigits returns the digits of a numbering system with a simple digit
// mapping, nil for any other.
func intlDigits(nu string) *[10]rune { return intlDigitTable()[nu] }

// intlNumberingSystems returns the numbering systems with simple digit
// mappings, sorted ("adlm", ..., "latn", ...).
var intlNumberingSystems = sync.OnceValue(func() []string {
	var list []string
	s := intlNumberingDigits
	for s != "" {
		end := strings.IndexByte(s, ';')
		list = append(list, s[:strings.IndexByte(s, ':')])
		s = s[end+1:]
	}
	return list
})

// intlDefaultNumberingSystem returns CLDR's default numbering system of an
// available locale of the constructors with locale data, latn for any
// other locale.
func intlDefaultNumberingSystem(tag string) string {
	i, ok := intlDataIndex(tag)
	if !ok {
		return "latn"
	}
	s := intlDefaultNumbering
	for range intlDataBase(i) {
		s = s[strings.IndexByte(s, ',')+1:]
	}
	if end := strings.IndexByte(s, ','); end >= 0 {
		return s[:end]
	}
	return s
}

// intlNumberingValues returns the "nu" locale data of an available locale
// of the constructors with locale data: its default numbering system first,
// then every numbering system with a simple digit mapping. The list is
// shared; callers must not modify it.
func intlNumberingValues(dataLocale string) []string {
	if i, ok := intlDataIndex(dataLocale); ok {
		return intlNumberingLists()[intlDataBase(i)]
	}
	return intlNumberingList(intlDefaultNumberingSystem(dataLocale))
}

// intlNumberingLists holds intlNumberingValues of each data locale.
var intlNumberingLists = sync.OnceValue(func() (lists [intlDataLocaleCount][]string) {
	for i := range lists {
		lists[i] = intlNumberingList(intlDefaultNumberingSystem(intlDataLocale(i)))
	}
	return lists
})

func intlNumberingList(def string) []string {
	all := intlNumberingSystems()
	list := make([]string, 0, len(all)+1)
	list = append(list, def)
	return append(list, all...)
}

// intlRecord finds the record of key in a table of "key:value;" records and
// returns its value.
func intlRecord(table, key string) (string, bool) {
	s := table
	for s != "" {
		end := strings.IndexByte(s, ';')
		rec := s[:end]
		if len(rec) > len(key) && rec[len(key)] == ':' && rec[:len(key)] == key {
			return rec[len(key)+1:], true
		}
		s = s[end+1:]
	}
	return "", false
}

// intlTimeData returns CLDR's timeData of a language and region: the
// preferred hour format and the allowed ones ("h", "h hb H hB"), from the
// record of language_region, else of the region, else of 001.
func intlTimeData(lang, region string) (preferred, allowed string) {
	v, ok := "", false
	if region != "" {
		if v, ok = intlRecord(intlHourData, lang+"_"+region); !ok {
			v, ok = intlRecord(intlHourData, region)
		}
	}
	if !ok {
		v, _ = intlRecord(intlHourData, "001")
	}
	preferred, allowed, _ = strings.Cut(v, " ")
	return preferred, allowed
}

// intlCharged charges a string an Intl formatter made to the realm's memory
// account, as intlString does (a byte per character of an ASCII string, two
// per UTF-16 unit otherwise), and returns it.
func (r *Realm) intlCharged(s *String) *String {
	n := s.Len()
	if s.kind != strASCII {
		n *= 2
	}
	r.chargeString(n)
	return s
}
